CONSOLE_HTML = """<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Governed Text-to-SQL</title><style>
:root{--bg:#07111f;--panel:#102039;--line:#294360;--ink:#edf4ff;--muted:#aab9cc;--ok:#53d39d;--no:#ff9893;--accent:#79a7ff;--warn:#f4c77a}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px system-ui,sans-serif}.wrap{max-width:1240px;margin:auto;padding:32px 18px}.eyebrow{color:var(--accent);font-weight:700;text-transform:uppercase;letter-spacing:.1em;font-size:12px}h1{margin:6px 0;font-size:32px}h2{font-size:14px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em;margin:0 0 10px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:18px}.wide{grid-column:1/-1}.card{border:1px solid var(--line);border-radius:12px;background:var(--panel);padding:17px}.note{color:var(--muted);line-height:1.5;margin:6px 0}.examples{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.example{border:1px solid var(--line);background:#0a1829;color:var(--ink);text-align:left;padding:12px;border-radius:8px;margin:0}.level{font-size:11px;color:var(--accent);font-weight:700}textarea,pre{width:100%;min-height:88px;margin:0;background:#091626;color:var(--ink);border:1px solid var(--line);border-radius:7px;padding:10px;font:13px ui-monospace,monospace;white-space:pre-wrap;overflow:auto}button{background:var(--accent);border:0;border-radius:7px;color:#07111f;padding:9px 12px;margin:8px 6px 0 0;font-weight:700;cursor:pointer}button.secondary{background:#294360;color:var(--ink)}button:disabled{opacity:.5;cursor:wait}.pill{padding:3px 8px;border-radius:999px;font-weight:700}.trusted,.proposed{background:#164837;color:var(--ok)}.refused,.failed_validation{background:#512d31;color:var(--no)}table{width:100%;border-collapse:collapse;font-size:13px}td,th{padding:7px;text-align:left;border-bottom:1px solid var(--line);color:var(--muted);white-space:nowrap}@media(max-width:780px){.grid,.examples{grid-template-columns:1fr}.wide{grid-column:auto}}
</style></head><body><main class="wrap"><header><div class="eyebrow">Synthetic data · governed review</div><h1>Text-to-SQL guardrails</h1><p class="note">Ask an analytical question, inspect the generated read-only SQL, then explicitly approve one bounded preview. No source account identifiers, exports, writes, or automatic execution.</p><p id="snapshot" class="note">Loading approved-snapshot status…</p></header>
<section class="grid"><div class="card wide"><h2>Start with an example</h2><div id="examples" class="examples"><p class="note">Loading examples…</p></div></div>
<div class="card wide"><h2>What this data contains</h2><p id="data-note" class="note">Loading curated-data disclosure…</p><div id="data" class="note">Loading safe preview…</div></div>
<div class="card"><h2>1. Ask a question</h2><textarea id="question">Show transaction counts by transaction type.</textarea><button id="propose">Create proposal</button><p id="proposal-status" class="note">No proposal created.</p></div>
<div class="card"><h2>2. Review and approve</h2><p class="note">Approval is single-use, expires in five minutes, and binds to this exact SQL plus the approved snapshot.</p><button id="approve" disabled>Approve and execute</button><p id="approval-status" class="note">Awaiting proposal.</p></div>
<div class="card wide"><h2>Proposed SQL</h2><textarea id="sql" readonly>—</textarea><p id="checks" class="note">—</p></div>
<div class="card"><h2>Curated lineage</h2><pre id="lineage">Loading…</pre></div><div class="card"><h2>Result preview</h2><div id="results" class="note">No execution has occurred.</div></div>
<div class="card"><h2>Safety boundary</h2><p class="note">Only approved tables and fields are allowed. The validator rejects writes, file/network access, unknown fields, identifier access, malformed SQL, and unbounded previews.</p></div><div class="card"><h2>Evaluation evidence</h2><p id="evaluation" class="note">Loading…</p></div></section></main>
<script>const $=s=>document.querySelector(s);let proposal;const esc=v=>String(v??'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));async function json(url,o){let r=await fetch(url,o);if(!r.ok)throw Error('Request failed ('+r.status+')');return r.json()}function rows(rows){if(!rows.length)return 'No rows returned.';return '<table><thead><tr>'+Object.keys(rows[0]).map(k=>'<th>'+esc(k)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+Object.values(r).map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}async function bootstrap(){let [s,c,e,d,x]=await Promise.all([json('/v1/status'),json('/v2/semantic-catalog'),json('/v1/evaluation'),json('/v2/data-preview'),json('/v2/examples')]);$('#snapshot').textContent='Snapshot: '+s.snapshot.state+' · '+(s.snapshot.source||s.snapshot.snapshot_sha256||s.snapshot.message);$('#lineage').textContent=JSON.stringify(c,null,2);$('#evaluation').textContent='Cases: '+e.case_count+' · execution accuracy: '+(e.metrics.execution_accuracy*100)+'% · safety rejection: '+(e.metrics.safety_rejection_rate*100)+'%';$('#data-note').textContent=d.disclosure||d.message;$('#data').innerHTML=rows(d.rows||[]);$('#examples').innerHTML=x.examples.map(a=>'<button class="example" data-q="'+esc(a.question)+'"><span class="level">'+esc(a.level)+'</span><br><strong>'+esc(a.title)+'</strong><br><span class="note">'+esc(a.concept)+'</span></button>').join('');document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>$('#question').value=b.dataset.q)}$('#propose').onclick=async()=>{let b=$('#propose');b.disabled=true;try{proposal=await json('/v2/query-proposals',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({question:$('#question').value})});$('#proposal-status').innerHTML='<span class="pill '+esc(proposal.status)+'">'+esc(proposal.status)+'</span> '+esc(proposal.reason||'Review required; no query executed.');$('#sql').value=proposal.generated_sql||'—';$('#checks').textContent=[...(proposal.validation_checks||[]),proposal.explain_summary||'',...(proposal.assumptions||[])].filter(Boolean).join(' → ');$('#approve').disabled=proposal.status!=='proposed';$('#approval-status').textContent=proposal.status==='proposed'?'Explicit approval is required.':'Proposal cannot be approved.'}catch(e){$('#proposal-status').textContent='Proposal failed safely: '+e.message}finally{b.disabled=false}};$('#approve').onclick=async()=>{if(!proposal)return;let b=$('#approve');b.disabled=true;try{let d=await json('/v2/query-proposals/'+proposal.proposal_id+'/execute',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({approval_token:proposal.approval_token})});$('#approval-status').innerHTML='<span class="pill '+esc(d.status)+'">'+esc(d.status)+'</span> '+esc(d.reason||'Approved, revalidated, and executed read-only.');$('#results').innerHTML=rows(d.result_preview||[])}catch(e){$('#approval-status').textContent='Execution failed safely: '+e.message}finally{b.disabled=false}};bootstrap();</script></body></html>"""
